    accepted: cursors.map(before => ({valid: true, data: {type: 'list_sessions', limit: 10, before}})),
    rejected: invalid.map(() => ({valid: false, error: 'list_sessions before must have a sessionId of 1–128 characters and a valid updatedAt date'})),
  });
});
EOF
